(function(){
'use strict';
const {cases,people}=ChatData,E=ChatEngine,h=E.escapeHTML;
const KEY='hospital-chat-lab:progress:v1';
let progress={completed:[],saved:[]},storageOK=true;
try{progress=E.sanitizeProgress(JSON.parse(localStorage.getItem(KEY)||'{}'),cases);}catch{storageOK=false;}
const sessions=new Map(),drafts=new Map();
let active='night',view='chat',filter='全部',query='',coachOpen=false,mobileList=false,phraseTab='all',toastTimer,dialogReturn=null,exportURL=null,exportText="";
const icons={
 chat:'<path d="M4 4h16v12H9l-5 4V4Z"/><path d="M8 8h8M8 12h5"/>',
 bookmark:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',
 chart:'<path d="M4 20h17M7 16v-4m5 4V8m5 8V4"/>',
 help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4m0 3h.01"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 back:'<path d="M20 12H4m6-6-6 6 6 6"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
 repeat:'<path d="M4 9a8 8 0 1 1 0 6M4 3v6h6"/>',
 send:'<path d="m3 3 18 9-18 9 4-9-4-9ZM7 12h14"/>',
 bulb:'<path d="M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2Z"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
 moon:'<path d="M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10Z"/>',
 layers:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',
 clipboard:'<rect x="5" y="5" width="14" height="16" rx="2"/><rect x="9" y="2" width="6" height="5" rx="1"/><path d="M9 12h6m-6 4h4"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18m-12 4h3"/>',
 message:'<path d="M3 4h18v13H8l-5 4V4Z"/><path d="M7 8h10M7 12h6"/>',
 file:'<path d="M5 3h10l4 4v14H5V3Zm9 0v5h5M9 12h6m-6 4h6"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-10h.01"/>',
 star:'<path d="m12 3 2.8 5.8 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.7l6.2-.9L12 3Z"/>'
};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.chat}</svg>`;}
function avatar(actor,cls=''){const p=people[actor];return `<span class="avatar ${actor} ${cls}"><img src="${h(p.image)}" alt="${h(p.name)}"></span>`;}
function getScene(id=active){return cases.find(s=>s.id===id)||cases[0];}
function session(id=active){if(!sessions.has(id))sessions.set(id,E.createSession(getScene(id)));return sessions.get(id);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(progress));storageOK=true;}catch{storageOK=false;toast('浏览器暂时不能保存记录，这次练习仍可继续。');}}
function toast(text){clearTimeout(toastTimer);const t=document.getElementById('toast');t.textContent=text;t.classList.add('visible');toastTimer=setTimeout(()=>t.classList.remove('visible'),2600);}
function rail(){return `<nav class="rail" aria-label="主导航"><button class="brand-mark" data-action="view" data-view="chat" aria-label="值班群聊首页">${icon('chat')}</button><span class="rail-line"></span>${[['chat','chat','会话'],['phrases','bookmark','话术'],['progress','chart','练习']].map(([id,ic,label])=>`<button class="rail-button ${view===id?'active':''}" data-action="view" data-view="${id}" ${view===id?'aria-current="page"':''} aria-label="${label}">${icon(ic)}<span>${label}</span></button>`).join('')}<div class="rail-bottom"><button class="rail-button" data-action="about" aria-label="使用说明">${icon('help')}<span>说明</span></button>${avatar('me','rail-avatar')}<span class="rail-caption">李晨光</span></div></nav>`;}
function sidebar(){return `<aside class="sidebar"><div class="side-heading"><div><h1>值班群聊<span class="tiny-dot"></span></h1><p>难开口的，先在这里练习。</p></div><span class="edition">01</span></div><label class="search">${icon('search')}<input id="search" type="search" placeholder="搜索情景、人物或关键词" value="${h(query)}" aria-label="搜索情景"></label><div class="filters" aria-label="情景分类">${['全部','上级','同事','安全'].map(f=>`<button data-action="filter" data-filter="${f}" class="${filter===f?'selected':''}" aria-pressed="${filter===f}">${f}</button>`).join('')}</div><div class="list-heading"><span>练习会话</span><span id="case-count">${cases.length}</span></div><div id="case-list" class="case-list"></div><div class="side-footer"><div><span>一点点，把话说清楚</span><b>${progress.completed.length}<em> / ${cases.length}</em></b></div><div class="mini-progress" aria-label="已完成 ${progress.completed.length} / ${cases.length} 个情景">${cases.map(s=>`<i class="${progress.completed.includes(s.id)?'filled':''}"></i>`).join('')}</div><small>${icon('lock')} ${storageOK?'进度保存在这台设备':'本次练习暂不持久保存'}</small></div></aside>`;}
function renderList(){const list=cases.filter(s=>(filter==='全部'||s.category===filter)&&[s.group,s.title,s.tag,s.context,'李晨光',...s.opening.map(x=>people[x[0]].name)].join(' ').toLowerCase().includes(query.trim().toLowerCase()));document.getElementById('case-count').textContent=String(list.length);document.getElementById('case-list').innerHTML=list.length?list.map(s=>{const ss=sessions.get(s.id),done=progress.completed.includes(s.id);return `<button class="case-item ${active===s.id&&view==='chat'?'active':''}" data-action="case" data-id="${s.id}" ${active===s.id&&view==='chat'?'aria-current="true"':''}><span class="case-symbol ${s.color}">${icon(s.icon)}</span><span class="case-copy"><span class="case-name">${h(s.group)}<small>${done?icon('check'):s.time}</small></span><span class="case-preview">${h(s.title)}</span><span class="case-meta">${h(s.tag)}<span>${ss?.ended?'已完成':ss?.history.length?`${ss.history.length}/3 轮`:'3 轮对话'}</span></span></span></button>`;}).join(''):`<div class="empty-list">${icon('search')}<p>没有找到这个情景</p><button class="text-button" data-action="clear-search">清空筛选</button></div>`;}
function header(scene,ss){return `<header class="chat-header"><button class="icon-button mobile-back" data-action="show-list" aria-label="返回会话列表">${icon('back')}</button><span class="case-symbol header-symbol ${scene.color}">${icon(scene.icon)}</span><div class="chat-title"><h2>${h(scene.group)} <span>（3）</span></h2><p><span class="status-dot"></span>虚构群聊 · 只有你在练习</p></div><div class="header-actions"><button class="icon-button" data-action="restart" aria-label="重新开始当前情景" title="重新开始">${icon('repeat')}</button><button class="icon-button coach-toggle ${coachOpen?'selected':''}" data-action="coach" aria-label="打开或关闭练习提示" aria-expanded="${coachOpen}">${icon('bulb')}</button></div></header><div class="scene-strip"><span>${icon('shield')} ${h(scene.title)}</span><span class="round-indicator">${ss.ended?'已完成':`${String(Math.min(ss.round+1,3)).padStart(2,'0')} / 03`}${ss.ended?'':'<span>轮</span>'}</span></div>`;}
function message(m,index,scene){const own=m.actor==='me';return `<div class="message ${own?'own':''}">${avatar(m.actor)}<div class="message-content"><div class="message-author">${h(people[m.actor].name)}${m.actor==='senior'?'<span>带教老师</span>':''}${own?'<span>你</span>':''}</div><div class="bubble">${h(m.text).replace(/\n/g,'<br>')}</div></div></div>`;}
function completion(scene,ss){const last=ss.history.at(-1);const unresolved=ss.mode==='pressure'||last?.response.kind!=='good';return `<section class="ending"><span class="ending-icon">${icon(unresolved?'shield':'check')}</span><div><small>三轮练习已完成</small><h3>${unresolved?'对话结束，安排仍需确认':'表达清楚了，再确认落实'}</h3><p>${h(unresolved?scene.escalation:scene.takeaway)}</p><p class="subtle">模拟回应不代表现实结果；需要的支持是否到位，仍要核实。</p><div class="ending-actions"><button class="primary small" data-action="export">${icon('download')} 导出这次复盘</button><button class="secondary small" data-action="next">下一个情景 ${icon('arrow')}</button></div></div></section>`;}
function messages(scene,ss){return `<div class="conversation" id="conversation" tabindex="0" aria-label="聊天消息"><div class="day-marker">周一 ${scene.time} · 模拟时间</div><div class="context-card"><span class="context-label">你现在的处境</span><p>${h(scene.context)}</p><span class="context-target">${icon('arrow')} ${h(scene.goal)}</span></div><div class="system-note">李晨光加入了练习 · 消息不会发送给真实同事</div><div class="message-log" role="log" aria-label="演练对话" aria-live="polite" aria-relevant="additions text">${ss.messages.map((m,i)=>message(m,i,scene)).join('')}${ss.pending?`<div class="message typing">${avatar(scene.rounds[ss.round].actor)}<div class="typing-indicator" aria-label="情景角色正在回复"><i></i><i></i><i></i></div></div>`:''}</div>${ss.ended?completion(scene,ss):''}</div>`;}
function composer(scene,ss){if(ss.ended)return `<div class="composer finished"><span>${icon('check')} 本次练习已结束 · 可以导出复盘或重新练习</span><button class="text-button" data-action="restart">再试一种说法 ${icon('repeat')}</button></div>`;return `<form class="composer" id="reply-form"><div class="composer-top"><span>${icon('bulb')} 卡住了？从一句话开始</span><div class="starter-chips">${['先说事实',scene.clinical?'补上风险':'说清影响','提出请求'].map((x,i)=>`<button type="button" data-action="fragment" data-index="${i}" ${ss.pending?'disabled':''}>${x} <span>＋</span></button>`).join('')}</div></div><label for="reply" class="sr-only">输入你的练习回复</label><textarea id="reply" rows="3" maxlength="600" placeholder="试着用自己的话回复。说明情况，再说你需要什么支持…" ${ss.pending?'disabled':''}>${h(drafts.get(active)||'')}</textarea><div class="composer-bottom"><div class="input-notes"><span>${icon('lock')} 不输入真实患者或个人信息</span><small><span id="char-count">${(drafts.get(active)||'').length}</span>/600 · ⌘ / Ctrl + Enter 发送</small></div><button class="send-button" type="submit" ${ss.pending?'disabled':''}>${ss.pending?'等待回应':'发送练习'} ${icon('send')}</button></div><p class="input-error" id="input-error" role="alert"></p></form>`;}
function checklist(analysis){return `<div class="checklist">${analysis.checks.map(c=>`<div class="check-item ${c.ok?'checked':''}"><span class="check-mark">${c.ok?icon('check'):'·'}</span><div><b>${c.label}</b><small>${c.ok?`已找到相关表达：${h(c.evidence)}`:h(c.tip)}</small></div></div>`).join('')}</div>`;}
function coach(scene,ss){const r=scene.rounds[Math.min(ss.round,2)],last=ss.history.at(-1),idx=ss.ended?2:Math.min(ss.round,2),saved=progress.saved.includes(`${active}:${idx}`);return `<aside class="coach ${coachOpen?'open':''}" aria-label="练习提示与复盘"><div class="coach-heading"><span>${icon('bulb')} 对话练习卡</span><button class="icon-button coach-close" data-action="coach" aria-label="关闭练习提示">${icon('close')}</button></div><div class="coach-scroll"><div class="cast"><div class="cast-avatars">${avatar('me')}${avatar('senior')}${avatar('peer')}</div><span>你与周老师、林医生<br><strong>把回应，练成自己的话。</strong></span></div><div class="step-track" aria-label="三轮练习进度">${['说清事实','接住施压','确认安排'].map((x,i)=>`<span class="${ss.round>i?'done':ss.round===i&&!ss.ended?'current':''}"><i>${ss.round>i?icon('check'):i+1}</i>${x}</span>`).join('')}</div><section class="coach-section"><p class="eyebrow">${ss.ended?'本次带走':'这一轮，试着做到'}</p><h3>${ss.ended?'对话有边界，行动有确认':h(r.label)}</h3><p>${h(ss.ended?scene.takeaway:r.prompt)}</p></section><div class="mode-control"><label for="mode">对方的回应方式</label><select id="mode" ${ss.history.length||ss.pending?'disabled':''}><option value="standard" ${ss.mode==='standard'?'selected':''}>协商练习</option><option value="pressure" ${ss.mode==='pressure'?'selected':''}>持续施压</option></select><small>${ss.mode==='pressure'?'对方会继续施压，练习坚持边界与寻求支持。':'回复会影响情景走向；开始后模式固定。'}</small></div>${last?`<section class="coach-section feedback-panel"><p class="eyebrow">第 ${last.round+1} 轮 · 表达复盘</p><h3>${h(last.analysis.headline)}</h3>${checklist(last.analysis)}${last.analysis.warnings.map(w=>`<p class="feedback-note">${icon('info')}<span>${h(w)}</span></p>`).join('')}<p class="next-tip">${h(last.analysis.next)}</p></section>`:`<section class="coach-section initial-check"><p class="eyebrow">一条好接的话，通常包含</p><div class="framework"><span>事实</span><i>→</i><span>${scene.clinical?'风险':'影响'}</span><i>→</i><span>请求</span></div><p>先说发生了什么，再说希望对方怎样帮忙。</p></section>`}<details class="example-card"><summary>${icon('message')} 看看这一轮可以怎么说 <span>＋</span></summary><p>${h(r.example)}</p><div><button class="text-button" data-action="copy-example" data-id="${active}" data-index="${idx}">${icon('copy')} 复制</button><button class="text-button ${saved?'is-saved':''}" data-action="save" data-id="${active}" data-index="${idx}" aria-pressed="${saved}">${icon('bookmark')} ${saved?'已收藏':'收藏'}</button>${!ss.ended?`<button class="text-button" data-action="insert-example">填入草稿</button>`:''}</div></details><div class="quiet-note">${icon('shield')}<p>有即时安全风险时，及时联系负责上级或院内应急链，不必先完成练习。</p></div><button class="text-button about-link" data-action="about">方法、来源与隐私 ${icon('arrow')}</button></div></aside>`;}
function chatView(){const scene=getScene(),ss=session();return `<main id="main" class="chat-panel">${header(scene,ss)}${messages(scene,ss)}${composer(scene,ss)}</main>${coach(scene,ss)}`;}
function pageHeader(kicker,title,desc){return `<div class="page-heading"><span class="eyebrow">${kicker}</span><h2>${title}</h2><p>${desc}</p></div>`;}
function phraseView(){const items=cases.flatMap(s=>s.rounds.map((r,i)=>({scene:s,r,i,key:`${s.id}:${i}`}))).filter(x=>phraseTab==='all'||progress.saved.includes(x.key));return `<main id="main" class="workspace-page">${pageHeader('WORDS TO TAKE WITH YOU','把好用的话，放进口袋。','选择贴合实际情况的表达，修改后再使用。所有示例都是虚构情景中的参考。')}<div class="page-tools"><div class="tabs"><button class="${phraseTab==='all'?'active':''}" data-action="phrase-tab" data-tab="all">全部话术 <b>24</b></button><button class="${phraseTab==='saved'?'active':''}" data-action="phrase-tab" data-tab="saved">我的收藏 <b>${progress.saved.length}</b></button></div><button class="secondary small" data-action="export-saved" ${!progress.saved.length?'disabled':''}>${icon('download')} 导出收藏</button></div><div class="phrase-grid">${items.length?items.map(({scene:s,r,i,key})=>`<article class="phrase-card"><div class="phrase-card-top"><span>${h(s.tag)} · 第 ${i+1} 轮</span><button class="icon-button ${progress.saved.includes(key)?'is-saved':''}" data-action="save" data-id="${s.id}" data-index="${i}" aria-pressed="${progress.saved.includes(key)}" aria-label="${progress.saved.includes(key)?'取消收藏':'收藏'} ${h(s.title)} 第 ${i+1} 轮">${icon('bookmark')}</button></div><h3>${h(r.label)}</h3><p>${h(r.example)}</p><footer><button class="text-button" data-action="case" data-id="${s.id}">去这个群练习 ${icon('arrow')}</button><button class="secondary small" data-action="copy-example" data-id="${s.id}" data-index="${i}">${icon('copy')} 复制</button></footer></article>`).join(''):`<div class="page-empty">${icon('bookmark')}<h3>把有用的第一句话留下来</h3><p>练习卡与话术卡上的收藏按钮，都可以保存参考表达。</p><button class="primary small" data-action="phrase-tab" data-tab="all">看看全部话术</button></div>`}</div></main>`;}
function progressView(){return `<main id="main" class="workspace-page">${pageHeader('ONE CONVERSATION AT A TIME','不必一次学会所有事。','每完成三轮对话，就点亮一个情景。这里记录练习，不给你的沟通能力打分。')}<section class="progress-hero"><div><span class="progress-big">${progress.completed.length}<small> / 8</small></span><p>已完成的情景</p></div><div><h3>${progress.completed.length===8?'八个难开口的时刻，你都练过了。':'今天，再练清楚一件事。'}</h3><div class="progress-track">${cases.map(s=>`<span class="${progress.completed.includes(s.id)?'filled':''}"></span>`).join('')}</div><p>会话内容刷新后清除；完成记录与话术收藏只保存在本机。</p></div></section><div class="progress-grid">${cases.map((s,i)=>`<button class="progress-card ${progress.completed.includes(s.id)?'done':''}" data-action="case" data-id="${s.id}"><span class="case-symbol ${s.color}">${icon(s.icon)}</span><span><small>情景 ${String(i+1).padStart(2,'0')} · ${h(s.tag)}</small><strong>${h(s.title)}</strong></span><span class="progress-state">${progress.completed.includes(s.id)?icon('check'):'去练习 '+icon('arrow')}</span></button>`).join('')}</div><div class="privacy-row"><p>${icon('lock')} ${storageOK?'只有完成情景与参考话术收藏会保存在浏览器。':'当前浏览器不支持持久保存，离开页面后记录可能丢失。'}</p><button class="text-button danger" data-action="clear">清除本机练习记录</button></div><div class="offline-card"><div>${icon('download')}<span><b>离线，也能练一遍。</b><small>包含全部人物、情景和话术，不需要 API。</small></span></div>${document.documentElement.dataset.offline==='true'?'<span class="offline-ready">当前已是离线版</span>':'<a class="secondary" href="hospital-chat-offline.html" download>下载离线版 '+icon('arrow')+'</a>'}</div></main>`;}
function render({scroll=false}={}){document.getElementById('app').className=`app view-${view} ${mobileList?'show-list':''} ${coachOpen?'show-coach':''}`;document.getElementById('app').innerHTML=rail()+sidebar()+(view==='chat'?chatView():view==='phrases'?phraseView():progressView());renderList();if(scroll)scrollChat();}
function scrollChat(){requestAnimationFrame(()=>{const el=document.getElementById('conversation');if(el)el.scrollTo({top:el.scrollHeight,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});}
function focusReply(){const el=document.getElementById('reply');if(el&&!el.disabled){el.focus();el.setSelectionRange(el.value.length,el.value.length);}}
function appendDraft(text){const current=drafts.get(active)||'';const value=current?current+'\n'+text:text;if(value.length>600){toast('草稿会超过 600 字，请先删减一些内容。');return;}drafts.set(active,value);const field=document.getElementById('reply');if(field){field.value=value;document.getElementById('char-count').textContent=String(value.length);focusReply();}}
function send(){const s=getScene(),ss=session(),text=document.getElementById('reply')?.value||'',result=E.submit(s,ss,text);if(!result.ok){document.getElementById('input-error').textContent=result.message;focusReply();return;}const token=++ss.revision,round=ss.round;ss.pending=true;ss.messages.push({actor:'me',text:result.text});drafts.delete(active);render({scroll:true});setTimeout(()=>{if(sessions.get(s.id)!==ss||ss.revision!==token)return;ss.pending=false;ss.messages.push(result.response);ss.history.push({...result,round});ss.round++;ss.ended=ss.round===s.rounds.length;if(ss.ended&&!progress.completed.includes(s.id)){progress.completed.push(s.id);persist();}if(active===s.id&&view==='chat'){render({scroll:true});if(innerWidth>760)focusReply();}},850);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制，可以按实际情况修改后使用。');}catch{openDialog('复制这段话',`<p>浏览器没有开放自动复制，可以手动选中下方文字。</p><textarea class="copy-fallback" readonly aria-label="待复制的话术">${h(text)}</textarea><button class="primary" data-action="close-dialog">完成</button>`);const el=document.querySelector('.copy-fallback');el.focus();el.select();}}
function download(name,text,type='text/markdown;charset=utf-8'){if(exportURL)URL.revokeObjectURL(exportURL);exportText=text;exportURL=URL.createObjectURL(new Blob([text],{type}));openDialog('导出前，检查一下',`<p>只保留虚构或去标识的内容。确认后下载 Markdown 文件，也可以直接复制。</p><textarea class="export-preview" readonly aria-label="复盘导出预览">${h(text)}</textarea><div class="dialog-actions"><button class="secondary" data-action="copy-export">${icon('copy')} 复制全部内容</button><a class="primary" href="${exportURL}" download="${h(name)}">${icon('download')} 下载 Markdown</a></div>`);}
function openDialog(title,content){const d=document.getElementById('dialog');dialogReturn=document.activeElement;d.innerHTML=`<div class="dialog-top"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="关闭">${icon('close')}</button></div><div class="dialog-body">${content}</div>`;if(!d.open)d.showModal();}
function closeDialog(){document.getElementById('dialog').close();if(exportURL){URL.revokeObjectURL(exportURL);exportURL=null;exportText='';}if(dialogReturn?.isConnected)dialogReturn.focus();}
function about(){openDialog('值班群聊 · 使用说明',`<p class="dialog-lead">把难开口的话，先在一个安全的地方说一遍。</p><h3>怎样练习</h3><ol><li>选择一个虚构群聊，读清“你现在的处境”。</li><li>自由输入你的回应，或用提示起草。消息只出现在本页。</li><li>完成三轮对话，查看表达复盘，复制话术或导出自己的练习。</li></ol><h3>模拟与反馈的边界</h3><p>本应用无需外部 AI。对话由预设分支与本地表达线索匹配驱动，可能漏判否定、反讽或复杂语境。提示帮助复盘，不验证事实、不评价职业能力，也不预测同事的真实反应。“持续施压”模式会刻意保留未解决的冲突。</p><p>患者安全表达要对应情景中真实存在的风险。个人健康、休息与公平分工也是可以直接讨论的需求。科研或一般材料问题，不需要编造患者伤害。</p><h3>隐私与离线</h3><p>不收集患者资料，不调用远程 AI，不发送聊天内容。输入与对话仅留在当前页面内存，刷新后清除；完成情景和固定话术收藏保存在本机。可识别信息检测只能发现部分格式，请主动使用虚构或去标识内容。导出复盘前请自行核对。</p><p>在线托管服务可能产生常规访问日志。下载离线版后可在本地打开，全部人物与情景均已包含。</p><h3>方法与来源</h3><p>练习参考结构化沟通、明确安全担忧与闭环确认思路，结合本院流程使用。若有即时危险，应立即联系负责上级、应急链或相应支持，不等群消息，也不为完成练习延误行动。</p><ul class="source-links"><li><a href="https://www.ahrq.gov/teamstepps-program/curriculum/mutual/tools/cus.html" target="_blank" rel="noopener noreferrer">AHRQ TeamSTEPPS · CUS：说明担忧与具体安全问题 ↗</a></li><li><a href="https://www.ahrq.gov/teamstepps-program/curriculum/mutual/tools/rule.html" target="_blank" rel="noopener noreferrer">AHRQ TeamSTEPPS · Two-Challenge Rule：未解决的安全担忧 ↗</a></li><li><a href="https://www.nhc.gov.cn/yzygj/c100068/201804/42ab2552298047679cd6ec733f233862.shtml" target="_blank" rel="noopener noreferrer">国家卫生健康委 · 医疗质量安全核心制度要点 ↗</a></li></ul><p class="subtle">来源核查：2026-11-04。台词为独立教学改编，不是机构原文。</p><h3>致谢</h3><p>感谢陈子杨（“中年男人陈子杨”）通过公开分享，为年轻医生适应职业初期的工作与人际挑战提供教学、经验和启发。本应用为独立教学改编，具体情景和话术并非其原话，也不代表其背书。</p><p class="subtle">李晨光沿用既有角色；周老师与林医生为配套虚构人物。情景不对应具体医院或个人。</p><div class="dialog-footer">${document.documentElement.dataset.offline==='true'?'<span>当前为完整离线版</span>':'<a class="secondary" href="hospital-chat-offline.html" download>'+icon('download')+' 下载离线版</a>'}<button class="primary" data-action="close-dialog">开始练习</button></div>`);}
function resetCurrent(){const mode=session().mode;sessions.set(active,E.createSession(getScene(),mode));drafts.delete(active);render();}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const a=button.dataset.action,id=button.dataset.id,index=Number(button.dataset.index);switch(a){
case 'view':view=button.dataset.view;mobileList=false;coachOpen=false;render();break;
case 'case':active=id;view='chat';mobileList=false;coachOpen=false;render({scroll:session().history.length>0});break;
case 'filter':filter=button.dataset.filter;document.querySelectorAll('.filters button').forEach(b=>{b.classList.toggle('selected',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter));});renderList();break;
case 'clear-search':query='';filter='全部';render();document.getElementById('search').focus();break;
case 'show-list':mobileList=true;coachOpen=false;render();break;
case 'coach':coachOpen=!coachOpen;render();break;
case 'fragment':appendDraft(getScene().rounds[session().round].fragments[index]);break;
case 'insert-example':appendDraft(getScene().rounds[session().round].example);coachOpen=false;render({scroll:true});focusReply();break;
case 'copy-example':copy(getScene(id).rounds[index].example);break;
case 'save':{const key=`${id}:${index}`;progress.saved=progress.saved.includes(key)?progress.saved.filter(x=>x!==key):[...progress.saved,key];persist();const scroll=document.querySelector('.coach-scroll')?.scrollTop||0;const convo=document.getElementById('conversation')?.scrollTop||0;const page=document.querySelector('.workspace-page')?.scrollTop||0;render();if(document.querySelector('.coach-scroll'))document.querySelector('.coach-scroll').scrollTop=scroll;if(document.getElementById('conversation'))document.getElementById('conversation').scrollTop=convo;if(document.querySelector('.workspace-page'))document.querySelector('.workspace-page').scrollTop=page;toast(progress.saved.includes(key)?'已加入话术收藏。':'已取消收藏。');break;}
case 'phrase-tab':phraseTab=button.dataset.tab;render();break;
case 'restart':if(session().messages.some(m=>m.actor==='me')||drafts.get(active)){openDialog('重新开始这个情景？','<p>当前会话和草稿会清除，完成记录与话术收藏保留。</p><div class="dialog-actions"><button class="secondary" data-action="close-dialog">继续当前练习</button><button class="primary" data-action="confirm-restart">重新开始</button></div>');}else resetCurrent();break;
case 'confirm-restart':closeDialog();resetCurrent();break;
case 'next':{const next=cases[(cases.findIndex(x=>x.id===active)+1)%cases.length];active=next.id;coachOpen=false;render();break;}
case 'export':download(`值班群聊-${getScene().id}-练习复盘.md`,E.transcript(getScene(),session()));break;
case 'export-saved':{let text='# 值班群聊｜我的话术收藏\n\n参考表达请按真实情况修改。\n\n';for(const key of progress.saved){const [sid,ri]=key.split(':'),s=getScene(sid);text+=`## ${s.title} · 第 ${Number(ri)+1} 轮\n\n${s.rounds[Number(ri)].example}\n\n`;}download('值班群聊-话术收藏.md',text);break;}
case 'copy-export':copy(exportText);break;
case 'about':about();break;
case 'close-dialog':closeDialog();break;
case 'clear':openDialog('清除本机练习记录？','<p>将清除本应用在这台设备上的完成记录、话术收藏，以及当前页面中的会话与草稿。</p><div class="dialog-actions"><button class="secondary" data-action="close-dialog">保留记录</button><button class="primary danger-fill" data-action="confirm-clear">清除这些记录</button></div>');break;
case 'confirm-clear':closeDialog();sessions.clear();drafts.clear();progress={completed:[],saved:[]};persist();render();toast('本应用的练习记录已清除。');break;
}});
document.addEventListener('input',event=>{if(event.target.id==='search'){query=event.target.value;renderList();}if(event.target.id==='reply'){drafts.set(active,event.target.value);document.getElementById('char-count').textContent=String(event.target.value.length);document.getElementById('input-error').textContent='';}});
document.addEventListener('change',event=>{if(event.target.id==='mode'&&!session().history.length&&!session().pending){session().mode=event.target.value==='pressure'?'pressure':'standard';render();}});
document.addEventListener('submit',event=>{if(event.target.id==='reply-form'){event.preventDefault();send();}});
document.addEventListener('keydown',event=>{if(event.target.id==='reply'&&!event.isComposing&&(event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();send();}});
document.getElementById('dialog').addEventListener('click',event=>{if(event.target===event.currentTarget)closeDialog();});
render();
})();
